#ifndef EXP_SETUP_H
#define EXP_SETUP_H

#include <immintrin.h>
#include <x86intrin.h>
#include <stdio.h>
#include <stdint.h>

#define END_TO_END 0

#define WARMUP_COUNT 100 // 00
#define REPEAT_COUNT 10000 // 00

#define SPLIT_VECTOR 8
#define SPLIT_VECTOR_4 4

#define TEST_DATA_SIZE 1024
#define TEST_INPUT_SIZE (SPLIT_VECTOR * 125) // 1000
#define TEST_INPUT_SIZE_DJIKSTRA (SPLIT_VECTOR * 4) // num edges -> 32*32 = 1024
#define TEST_INPUT_SIZE_RSORT (SPLIT_VECTOR * 10) // 80

__attribute__((target("clflushopt")))
void clean_cache(void *addr, int64_t size) {
    for (int64_t i = 0; i < size; i += 64) {
        _mm_clflushopt(addr + i);
    }
    _mm_mfence();
}


#define START_TIME() \
    uint64_t start, end; \
    int temp = 0; \
    _mm_mfence(); \
    start = __rdtscp(&temp); \

#define END_TIME() \
    _mm_mfence(); \
    fprintf(stderr, "Elapsed time in %s: %llu\n", \
        __FILE__, \
        __rdtscp(&temp) - start);

static char *random_content = "";

#endif